mapper.update:
UPDATE payment_order_notifications SET status = 'DONE', notified_at = CURRENT_TIMESTAMP(6),
    claim_token = NULL, lease_until = NULL, last_error = NULL
WHERE order_id = #{orderId} AND status = 'PROCESSING' AND claim_token = #{token}

UPDATE payment_order_notifications SET status = #{status}, claim_token = NULL, lease_until = NULL,
    next_attempt_at = TIMESTAMPADD(SECOND, #{delaySeconds}, CURRENT_TIMESTAMP(6)), last_error = #{error}
WHERE order_id = #{orderId} AND status = 'PROCESSING' AND claim_token = #{token}
